<?php $xtreampiPageScripts=['assets/xtreampi/category.js'];$editing=is_array($rCategoryArr??null)&&intval($rCategoryArr['id']??0)>0;$value=static fn(string $key,string $default=''):string=>htmlspecialchars((string)($rCategoryArr[$key]??$default),ENT_QUOTES,'UTF-8');?>
<section class="sc-group-editor" data-sc-category-editor><div class="sc-page-heading"><div><p class="sc-eyebrow">Content Setup</p><h1><?php echo $editing?'Edit Category':'Add Category';?></h1></div><div class="sc-page-actions"><a class="sc-button sc-button-secondary" href="stream_categories"><i class="fe-chevron-left"></i> Back to categories</a></div></div>
<form class="sc-form sc-group-form" action="post.php?action=stream_category&amp;referer=stream_categories" method="post" enctype="multipart/form-data"><?php if($editing):?><input type="hidden" name="edit" value="<?php echo intval($rCategoryArr['id']);?>"><input type="hidden" name="cat_order" value="<?php echo intval($rCategoryArr['cat_order']??0);?>"><input type="hidden" name="category_type" value="<?php echo $value('category_type');?>"><?php endif;?>
<section class="sc-form-section"><h2>Category Details</h2><div class="sc-form-grid"><?php if(!$editing):?><label>Content Type<select name="category_type" required><option value="live">Live TV</option><option value="movie">Movies</option><option value="series">TV Series</option><option value="radio">Radio</option></select></label><?php else:?><label>Content Type<input type="text" value="<?php echo ucfirst($value('category_type'));?>" disabled></label><?php endif;?><label>Category Name<input type="text" name="category_name" required value="<?php echo $value('category_name');?>" placeholder="Category name"></label></div><div class="sc-mag-policies"><div class="sc-package-options"><label class="sc-selection-card"><input type="checkbox" name="is_adult"<?php echo !empty($rCategoryArr['is_adult'])?' checked':'';?>><span><strong>Adult content</strong><small>Mark this category as restricted adult content.</small></span></label></div></div></section>
<div class="sc-form-error" data-sc-category-error hidden></div><div class="sc-form-actions"><button class="sc-button sc-button-primary" type="submit" name="submit_category" value="<?php echo $editing?'Edit':'Add';?>"><?php echo $editing?'Save Category':'Add Category';?></button><a class="sc-button sc-button-secondary" href="stream_categories">Cancel</a></div></form></section>
